INSERT INTO public.promotions (id, code, title, description, discount_type, discount_value, min_order_value, max_discount, start_date, end_date, usage_limit, used_count, category, applicable_origin, applicable_destination, badge_text, terms, is_active, created_at) VALUES
(1, 'SAPA20', 'Giảm 20% Vé Đi Sa Pa Mùa Thu Vàng', 'Ưu đãi đặc biệt giảm 20% cho các chuyến xe Hà Nội đi Sa Pa và chiều ngược lại', 'PERCENT', 20.00, 300000.00, 100000.00, '2026-10-29 06:38:16.540144', '2027-01-27 06:38:16.540144', 500, 375, 'HOT_ROUTE', 'Hà Nội', 'Sa Pa', 'GIẢM 20%', 'Áp dụng cho mọi chuyến xe đi Sa Pa. Hạn sử dụng đến 30/11/2026.', TRUE, '2026-10-29 06:38:16.540144'),
(2, 'DALATVIP', 'Giảm 50.000đ Limousine Đà Lạt', 'Chuyến đi Sài Gòn - Đà Lạt thêm êm ái với mức giảm 50.000đ cho mỗi vé Limousine', 'FIXED', 50000.00, 250000.00, 50000.00, '2026-10-29 06:38:16.540144', '2027-01-27 06:38:16.540144', 1000, 680, 'HOT_ROUTE', 'TP. Hồ Chí Minh', 'Đà Lạt', 'GIẢM 50K', 'Áp dụng cho các nhà xe chất lượng cao tuyến TP.HCM - Đà Lạt.', TRUE, '2026-10-29 06:38:16.540144'),
(3, 'WELCOME50', 'Chào Bạn Mới - Giảm 15% Vé Đầu Tiên', 'Dành riêng cho khách hàng đăng ký tài khoản mới và đặt vé lần đầu tiên trên TravelEasy', 'PERCENT', 15.00, 150000.00, 80000.00, '2026-10-29 06:38:16.540144', '2027-01-27 06:38:16.540144', 2000, 1420, 'NEW_CUSTOMER', NULL, NULL, 'BẠN MỚI 15%', 'Chỉ áp dụng cho tài khoản chưa từng hoàn tất chuyến đi nào trên hệ thống.', TRUE, '2026-10-29 06:38:16.540144'),
(4, 'PAYOS50', 'Giảm 30.000đ Khi Quét Mã VietQR / PayOS', 'Thanh toán trực tuyến không tiền mặt qua cổng PayOS hoặc quét mã VietQR ngân hàng', 'FIXED', 30000.00, 200000.00, 30000.00, '2026-10-29 06:38:16.540144', '2027-01-27 06:38:16.540144', 1500, 890, 'ONLINE_PAYMENT', NULL, NULL, 'PAYOS -30K', 'Áp dụng tự động khi chọn hình thức thanh toán VietQR / PayOS tại bước thanh toán.', TRUE, '2026-10-29 06:38:16.540144'),
(5, 'VETAO15', 'Giảm 15% Tuyến Biển Vũng Tàu - Nha Trang', 'Kỳ nghỉ biển trọn vẹn với vé xe giường nằm và limousine giảm ngay 15%', 'PERCENT', 15.00, 200000.00, 60000.00, '2026-10-29 06:38:16.540144', '2027-01-27 06:38:16.540144', 800, 410, 'HOT_ROUTE', 'TP. Hồ Chí Minh', 'Vũng Tàu', 'BIỂN XANH 15%', 'Áp dụng cho tuyến TP.HCM đi Vũng Tàu, Nha Trang, Phan Thiết.', TRUE, '2026-10-29 06:38:16.540144'),
(6, 'HOTLINE10', 'Tri Ân Khách Hàng Thân Thiết - Giảm 10%', 'Mã giảm giá định kỳ dành tặng hành khách đồng hành cùng TravelEasy', 'PERCENT', 10.00, 100000.00, 50000.00, '2026-10-29 06:38:16.540144', '2027-01-27 06:38:16.540144', 3000, 2150, 'ALL', NULL, NULL, 'TRI ÂN 10%', 'Áp dụng cho toàn bộ các tuyến đường trên toàn quốc.', TRUE, '2026-10-29 06:38:16.540144');
INSERT INTO public.review_reports (id, created_at, rating, reason, reporter_email, review_author, review_snippet, status) VALUES
(1, '2026-10-27 05:38:11.782859', 5, 'Đánh giá tích cực cần ghim trang chủ', 'operator@futa.vn', 'Nguyễn Văn Du Khách', 'Xe chạy rất đúng giờ, tài xế lái cẩn thận, phục vụ nước ngọt miễn phí', 'APPROVED'),
(2, '2026-10-28 05:38:11.782859', 1, 'Khách báo cáo thái độ phục vụ chưa đạt chuẩn', 'thanhphong@gmail.com', 'Hoàng Tuấn Anh', 'Tài xế đón khách dọc đường trễ 20 phút', 'PENDING'),
(3, '2026-10-25 05:38:11.782859', 4, 'Cần nhắc nhở phụ xe cung cấp thêm chăn ấm', 'admin@gmail.com', 'Trần Minh Đức', 'Giường nằm êm ái, wifi mạnh, chỉ có điều máy lạnh hơi rét vào ban đêm', 'RESOLVED'),
(4, '2026-10-24 05:38:11.782859', 5, 'Đánh giá chất lượng 5 sao xuất sắc', 'operator@thanhbuoi.com.vn', 'Lê Bích Ngọc', 'Phòng cung điện VIP quá đẹp, đi Đà Lạt ngủ một giấc tới nơi sảng khoái', 'APPROVED'),
(5, '2026-10-23 05:38:11.782859', 5, 'Trải nghiệm số hóa tuyệt vời', 'customer@gmail.com', 'Phạm Thu Hằng', 'Đặt vé online cực kỳ tiện, quét mã QR lên xe không cần in vé giấy', 'APPROVED'),
(6, '2026-10-29 03:04:04.405545', 5, 'Đánh giá tích cực nổi bật', 'cust01@gmail.com', 'Đỗ Thảo Vy', 'Xe chạy êm ru, cabin đôi có tivi và tai nghe riêng rất riêng tư', 'APPROVED'),
(7, '2026-10-29 03:04:04.405545', 4, 'Góp ý về thời gian đón khách', 'cust02@gmail.com', 'Vũ Minh Trí', 'Bác tài đón trễ 15 phút do kẹt xe nhưng đã gọi điện báo trước chu đáo', 'RESOLVED'),
(8, '2026-10-29 04:04:04.405545', 5, 'Đánh giá tốt chất lượng dịch vụ', 'cust03@gmail.com', 'Bùi Quỳnh Nga', 'Xe Limousine Hoa Mai rất mới, ghế massage hoạt động tốt', 'APPROVED'),
(9, '2026-10-29 04:04:04.405545', 3, 'Phản ánh kỹ thuật điều hòa trên xe', 'cust04@gmail.com', 'Dương Tuấn Khang', 'Điều hòa phả hơi lạnh hơi mạnh ở hàng ghế cuối', 'PENDING'),
(10, '2026-10-29 05:04:04.405545', 5, 'Khen ngợi trải nghiệm tiện ích', 'cust05@gmail.com', 'Lâm Gia Hân', 'Nhà xe Sao Việt phục vụ nước suối và bánh ngọt nhẹ, rất hài lòng', 'APPROVED'),
(11, '2026-10-29 05:04:04.405545', 5, 'Trải nghiệm số hóa tiện lợi', 'hungnv@gmail.com', 'Nguyễn Văn Hùng', 'Quẹt mã QR lên xe cực nhanh, không cần in vé giấy', 'APPROVED'),
(12, '2026-10-29 05:19:04.405545', 5, 'Khen ngợi thái độ phục vụ của phụ xe', 'linhtk@gmail.com', 'Trịnh Khánh Linh', 'Bị say xe nên nhờ tài xế đổi lên giường đầu, phụ xe rất nhiệt tình hỗ trợ', 'RESOLVED'),
(13, '2026-10-29 05:34:04.405545', 3, 'Đề xuất kéo dài thời gian dừng nghỉ chân', 'kietdt@gmail.com', 'Đặng Tuấn Kiệt', 'Thời gian dừng trạm nghỉ hơi ngắn, chỉ có 15 phút', 'PENDING'),
(14, '2026-10-29 05:44:04.405545', 5, 'Đánh giá tích cực tuyến Sa Pa', 'anhvm@gmail.com', 'Võ Mai Anh', 'Chuyến đi Hà Nội - Lào Cai đường cao tốc êm, ngủ một giấc là đến', 'APPROVED'),
(15, '2026-10-29 05:54:04.405545', 4, 'Đánh giá cao tính minh bạch tài chính', 'trongpd@gmail.com', 'Phạm Đức Trọng', 'Phí hủy vé tính đúng theo cam kết minh bạch của sàn TravelEasy', 'RESOLVED');
INSERT INTO public.reviews (id, user_id, customer_name, booking_id, booking_code, trip_id, bus_company_id, bus_company_name, route_name, rating, punctuality_rating, cleanliness_rating, service_rating, comment, image_urls, company_reply, status, created_at) VALUES
(1, 3, 'Nguyễn *** Khách', 1, 'BKG-20261025-001', 1, 1, 'Phương Trang (FUTA Bus Lines)', 'TP. Hồ Chí Minh - Đà Lạt', 5, 5.0, 4.8, 4.9, 'Xe chạy rất êm, tài xế đúng giờ và không đón khách dọc đường. Phòng cabin riêng tư có sạc điện thoại và rèm che rất kín đáo. Lần tới đi Đà Lạt nhất định tiếp tục đặt TravelEasy!', 'https://images.unsplash.com/photo-1544620347-c4fd4a3d5957?w=600&auto=format&fit=crop&q=80,https://images.unsplash.com/photo-1570125909232-eb263c188f7e?w=600&auto=format&fit=crop&q=80', 'Cảm ơn quý khách đã tin tưởng dịch vụ Phương Trang FUTA Bus Lines trên nền tảng TravelEasy. Chúc quý khách luôn có những chuyến đi thật vui vẻ và bình an!', 'APPROVED', '2026-10-29 06:39:15.965047'),
(2, 9, 'Trần *** Ngọc', 2, 'BKG-20261021-002', 5, 5, 'Xe Khách Hoa Mai', 'TP. Hồ Chí Minh - Vũng Tàu', 5, 5.0, 5.0, 4.8, 'Limousine Hoa Mai đón đúng giờ tại Hàng Xanh. Bác tài thân thiện, lái xe an toàn, không phóng nhanh vượt ẩu. Ghế massage ngồi cực sướng!', 'https://images.unsplash.com/photo-1494515843206-f3117d3f51b7?w=600&auto=format&fit=crop&q=80', 'Hoa Mai xin cảm ơn những nhận xét chân thành của quý khách. Hân hạnh được phục vụ bạn trên những hành trình tiếp theo!', 'APPROVED', '2026-10-29 06:39:15.965047'),
(3, 10, 'Lê *** Cường', 3, 'BKG-20261021-003', 8, 1, 'Phương Trang (FUTA Bus Lines)', 'TP. Hồ Chí Minh - Phan Thiết', 4, 4.8, 4.5, 4.7, 'Chất lượng xe tương đối tốt, máy lạnh mát rượi. Điểm dừng chân vệ sinh sạch sẽ, đồ ăn hợp túi tiền. Trừ 1 sao nhỏ vì bến xe hơi đông đúc lúc lên xe.', NULL, 'TravelEasy và nhà xe ghi nhận góp ý của bạn về việc phân luồng tại bến xe để nâng cao trải nghiệm khách hàng trong tương lai.', 'APPROVED', '2026-10-29 06:39:15.965047'),
(4, 11, 'Phạm *** Dũng', 4, 'BKG-20261021-004', 11, 6, 'Hoàng Long Asia', 'Hà Nội - Hạ Long', 5, 4.9, 4.9, 5.0, 'Xe đón đúng hẹn tại Mỹ Đình. Xe mới, chăn gối sạch thơm mùi sả chanh. Điểm 10 cho bác phụ xe hỗ trợ xách vali rất nhiệt tình!', 'https://images.unsplash.com/photo-1517649763962-0c623266ddc0?w=600&auto=format&fit=crop&q=80', 'Hoàng Long Asia trân trọng cảm ơn quý khách đã đồng hành!', 'APPROVED', '2026-10-29 06:39:15.965047'),
(5, 12, 'Hoàng *** Mai', 5, 'BKG-20261021-005', 12, 7, 'Nhà Xe Văn Minh', 'Hà Nội - Vinh', 5, 5.0, 5.0, 5.0, 'Xe Văn Minh thì đẳng cấp khỏi bàn rồi, dịch vụ chu đáo như hàng không mặt đất. Nước ngọt và bánh quy phát miễn phí tận giường.', NULL, 'Nhà Xe Văn Minh trân trọng cảm ơn quý khách!', 'APPROVED', '2026-10-29 06:39:15.965047'),
(6, 3, 'Nguyễn *** Khách', 6, 'BKG-20261021-006', 15, 10, 'Chín Nghĩa', 'Đà Nẵng - Quy Nhơn', 4, 4.7, 4.6, 4.8, 'Chuyến xe êm ái, xe chạy đúng tuyến không vòng vo bắt khách. Giá vé dịp cuối tuần rất hợp lý.', NULL, NULL, 'APPROVED', '2026-10-29 06:39:15.965047'),
(7, 3, 'Nguyễn *** Khách', 7, 'BKG-20261029-007', 21, 1, 'Phương Trang (FUTA Bus Lines)', 'TP. Hồ Chí Minh - Đà Lạt', 5, 5.0, 4.9, 5.0, 'Xe chạy rất đúng giờ, xe sạch sẽ và bác tài lái xe cẩn thận. Rất hài lòng!', NULL, NULL, 'APPROVED', '2026-10-29 13:57:39.544729'),
(8, 12, 'Hoàng *** Mai', 27, 'BKG-20261029-027', 41, 1, 'Phương Trang (FUTA Bus Lines)', 'TP. Hồ Chí Minh - Phan Thiết', 5, 5.0, 5.0, 5.0, 'Fake review', NULL, NULL, 'APPROVED', '2026-10-31 16:33:30.561750'),
(9, 9, 'Trần *** Ngọc', 49, 'BK-20261110-CT01', 700, 14, 'Công Thành', 'TP. Hồ Chí Minh - Vũng Tàu', 5, 5.0, 5.0, 5.0, 'Xe Limousine Công Thành cực kỳ êm ái, xe mới tinh thơm mát. Bác tài chạy rất điềm đạm, đón đúng giờ tại Bến xe Miền Đông Mới. Rất hài lòng với dịch vụ!', NULL, 'Nhà xe Công Thành chân thành cảm ơn chị Ngọc đã tin tưởng trải nghiệm dịch vụ. Chúc chị một chuyến đi Vũng Tàu thật vui vẻ và bình an!', 'APPROVED', '2026-11-10 04:43:38.322686'),
(10, 10, 'Lê *** Cường', 50, 'BK-20261110-CT02', 700, 14, 'Công Thành', 'TP. Hồ Chí Minh - Vũng Tàu', 5, 4.8, 5.0, 4.9, 'Ghế massage ngồi cực sướng, trên xe có cổng sạc Type-C tiện lợi và wifi mượt. Nước uống khăn lạnh phát tận nơi. 5 sao cho chất lượng của nhà xe Công Thành.', NULL, 'Dạ nhà xe Công Thành cảm ơn anh Cường rất nhiều ạ. Chúng tôi sẽ không ngừng hoàn thiện để mang lại trải nghiệm tốt nhất cho quý khách!', 'APPROVED', '2026-11-10 05:43:38.322686');
